(()=>{const form=document.getElementById('homeowner-form'),yard=document.getElementById('yard-step'),contact=document.getElementById('contact-step'),label=document.getElementById('step-label'),status=document.getElementById('home-status');const started=Date.now(),submissionId=crypto.randomUUID();const incomingZip=new URLSearchParams(location.search).get('zip');if(incomingZip&&/^[0-9]{5}$/.test(incomingZip))form.elements.zip.value=incomingZip;const key="sb_publishable_KQGD-vWlAlJi_Bv7fSaEvA_YLJpIgyu";const source={};const params=new URLSearchParams(location.search);for(const k of ['utm_source','utm_medium','utm_campaign','utm_content','utm_term']){const v=params.get(k);if(v)source[k]=v.slice(0,160)}try{if(document.referrer)source.referrer=new URL(document.referrer).hostname}catch{}const services=()=>Array.from(form.querySelectorAll('input[name=services]:checked')).map(i=>i.value);const motion=()=>matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth';document.getElementById('next-step').onclick=()=>{for(const i of yard.querySelectorAll('input,select'))if(!i.reportValidity())return;const error=document.getElementById('services-error');error.hidden=services().length>0;if(!error.hidden){error.scrollIntoView({block:'center'});return}contact.disabled=false;contact.hidden=false;yard.hidden=true;label.textContent='Step 2 of 2 · Contact details';document.getElementById('yard-summary').textContent=form.elements.address.value+', '+form.elements.city.value+' '+form.elements.zip.value+' · '+services().map(s=>({mowing:'Lawn mowing',edging:'Edging & trimming',hedges:'Hedges',leaves:'Leaf removal',cleanup:'Yard cleanup',mulch:'Mulch & beds'})[s]).join(', ');contact.querySelector('input').focus({preventScroll:true});label.scrollIntoView({behavior:motion(),block:'start'})};document.getElementById('back-step').onclick=()=>{contact.hidden=true;contact.disabled=true;yard.hidden=false;label.textContent='Step 1 of 2 · Your yard';yard.querySelector('input').focus({preventScroll:true});label.scrollIntoView({behavior:motion(),block:'start'})};const today=new Date();form.elements.preferred_date.min=[today.getFullYear(),String(today.getMonth()+1).padStart(2,'0'),String(today.getDate()).padStart(2,'0')].join('-');form.onsubmit=async e=>{e.preventDefault();if(contact.hidden||!form.reportValidity())return;const button=document.getElementById('home-submit');button.disabled=true;button.textContent='Saving your request…';status.textContent='';const data=new FormData(form);const body={kind:'homeowner',notice_version:'2026-10-07',submission_id:submissionId,elapsed_ms:Date.now()-started,source,services:services(),request_consent:data.get('request_consent')==='on'};for(const k of ['address','city','state','zip','email','first_name','phone','frequency','lawn_height','access_notes','preferred_date','website'])body[k]=data.get(k)||'';try{const r=await fetch('https://pzymmsfjgspvzbivzvkx.supabase.co/functions/v1/mowmatter-capture',{method:'POST',headers:{apikey:key,'Content-Type':'application/json'},body:JSON.stringify(body),signal:AbortSignal.timeout(15000)});const result=await r.json();if(!r.ok||!result.ok)throw new Error(result.error||'Please try again.');status.className='success';status.textContent='Your lawn care request is saved. We’ll review local availability and contact you about the next step. No provider, price or service date is confirmed yet.';contact.disabled=true;button.textContent='Request saved';status.focus({preventScroll:true});status.scrollIntoView({block:'center',behavior:motion()})}catch(err){status.className='error';status.textContent=err.name==='TimeoutError'?'That took too long. Your details are still here—please try again.':err.message||'We could not save your request. Please try again.';button.disabled=false;button.textContent='Try again';status.focus({preventScroll:true})}}})();
